def _components(grid, ignored_color):
    h, w = len(grid), len(grid[0])
    seen = set(); comps = []
    for r in range(h):
        for c in range(w):
            if (r,c) in seen or grid[r][c] == ignored_color: continue
            color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color,cells))
    return comps

def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={x:sum(row.count(x) for row in grid) for x in set(v for row in grid for v in row)}
    bg=max(counts,key=counts.get)
    comps=_components(grid,bg)
    markers=[]
    for color,cells in comps:
        rs=[r for r,c in cells];cs=[c for r,c in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs);hh=r1-r0+1;ww=c1-c0+1;S=set(cells)
        if len(cells)==hh+ww-1 and hh>=3 and ww>=3:
            for cr,cc in cells:
                if sum((cr,x) in S for x in range(c0,c1+1))==ww and sum((y,cc) in S for y in range(r0,r1+1))==hh:
                    markers.append((hh*ww,color,S,cr,cc,r0,r1,c0,c1));break
    if not markers:return [row[:] for row in grid]
    _,mc,mark,cr,cc,r0,r1,c0,c1=max(markers)
    # The target lies along the diagonal extending into the quadrant opposite the L arms.
    dr=1 if cr>r0 else -1
    dc=1 if cc>c0 else -1
    # The arms encode the slope of the selection ray: vertical/horizontal.
    vlen=abs(cr-r0)+1 if cr==r1 else abs(r1-cr)+1
    hlen=abs(cc-c0)+1 if cc==c1 else abs(c1-cc)+1
    candidates=[]
    for color,cells in comps:
        if color==mc or len(cells)<2 or any((r,c) in mark for r,c in cells): continue
        scores=[]
        for r,c in cells:
            u=(r-cr)*dr; v=(c-cc)*dc
            if u>0 and v>0:
                # Cross-product distance to the arm-defined ray, then distance along it.
                scores.append((abs(u*hlen-v*vlen),u+v))
        if scores:
            err=min(e for e,d in scores)
            depth=min(d for e,d in scores if e==err)
            candidates.append((err,depth,cells))
    if not candidates:return [row[:] for row in grid]
    _,_,target=min(candidates,key=lambda x:(x[0],x[1]))
    out=[row[:] for row in grid]
    for r,c in target:out[r][c]=mc
    return out

